<?php

declare(strict_types=1);

namespace App\Modules\Automation\Console\Experiments\Datasets;

use App\Support\Experiments\SeededRandom;
use InvalidArgumentException;

/**
 * The E2 dataset (evaluation-methodology.md §2): 300 labelled pairs — 100 duplicates (60 generated by
 * dropping and swapping words of a generated ticket, 40 hand-written) and 200 non-duplicates (50 from
 * the same category, 150 from different categories) — plus a haystack of 5 000 generated tickets for Recall@5.
 */
final class DuplicatePairsGenerator
{
    public const int GENERATED_DUPLICATES = 60;

    public const int HAND_WRITTEN_DUPLICATES = 40;

    public const int SAME_CATEGORY_NON_DUPLICATES = 50;

    public const int OTHER_NON_DUPLICATES = 150;

    public const int HAYSTACK = 5000;

    public function __construct(private TicketTextGenerator $texts = new TicketTextGenerator) {}

    /**
     * @param  list<array{category: string, a: array{title: string, description: string}, b: array{title: string, description: string}}>  $handWritten
     * @return list<array{id: string, label: string, source: string, category_a: string, category_b: string, a: array{title: string, description: string}, b: array{title: string, description: string}}>
     */
    public function pairs(int $seed, array $handWritten): array
    {
        if (count($handWritten) !== self::HAND_WRITTEN_DUPLICATES) {
            throw new InvalidArgumentException(sprintf('Expected %d hand-written duplicate pairs, got %d.', self::HAND_WRITTEN_DUPLICATES, count($handWritten)));
        }

        $random = new SeededRandom($seed);
        $categories = TicketTextGenerator::categories();
        $pairs = [];

        for ($i = 0; $i < self::GENERATED_DUPLICATES; $i++) {
            $category = $categories[$i % count($categories)];
            $original = $this->texts->ticket($random, $category);
            $pairs[] = $this->pair('duplicate', 'generated: words dropped and swapped', $category, $category, $original, $this->variant($random, $original));
        }

        foreach ($handWritten as $pair) {
            $pairs[] = $this->pair('duplicate', 'hand-written', $pair['category'], $pair['category'], $pair['a'], $pair['b']);
        }

        for ($i = 0; $i < self::SAME_CATEGORY_NON_DUPLICATES; $i++) {
            $category = $categories[$i % count($categories)];
            $a = $this->texts->ticket($random, $category);
            $b = $this->texts->ticket($random, $category, avoidObject: $a['object']);
            $pairs[] = $this->pair('non_duplicate', 'generated: same category, different object', $category, $category, $a, $b);
        }

        for ($i = 0; $i < self::OTHER_NON_DUPLICATES; $i++) {
            $first = $categories[$i % count($categories)];
            do {
                $second = $random->pick($categories);
            } while ($second === $first);
            $pairs[] = $this->pair('non_duplicate', 'generated: different categories', $first, $second, $this->texts->ticket($random, $first), $this->texts->ticket($random, $second));
        }

        foreach ($pairs as $index => &$pair) {
            $pair = ['id' => sprintf('P%03d', $index + 1), ...$pair];
        }

        return $pairs;
    }

    /**
     * @return list<array{id: string, category: string, title: string, description: string}>
     */
    public function haystack(int $seed): array
    {
        $random = new SeededRandom($seed);
        $categories = TicketTextGenerator::categories();
        $tickets = [];

        for ($i = 1; $i <= self::HAYSTACK; $i++) {
            $category = $random->pick($categories);
            $text = $this->texts->ticket($random, $category);
            $tickets[] = ['id' => sprintf('H%04d', $i), 'category' => $category, 'title' => $text['title'], 'description' => $text['description']];
        }

        return $tickets;
    }

    /**
     * A generated duplicate: the same report written a little differently — one to three words of the
     * description dropped, sometimes one title word, and one or two neighbouring words swapped.
     *
     * @param  array{title: string, description: string}  $original
     * @return array{title: string, description: string}
     */
    public function variant(SeededRandom $random, array $original): array
    {
        $title = explode(' ', $original['title']);
        $description = explode(' ', $original['description']);

        if (count($title) > 2 && $random->chance(0.5)) {
            array_splice($title, $random->int(1, count($title) - 1), 1);
        }
        for ($drops = $random->int(1, 3); $drops > 0 && count($description) > 4; $drops--) {
            array_splice($description, $random->int(0, count($description) - 1), 1);
        }
        for ($swaps = $random->int(1, 2); $swaps > 0; $swaps--) {
            $at = $random->int(0, count($description) - 2);
            [$description[$at], $description[$at + 1]] = [$description[$at + 1], $description[$at]];
        }

        return ['title' => implode(' ', $title), 'description' => implode(' ', $description)];
    }

    /**
     * @param  array{title: string, description: string}  $a
     * @param  array{title: string, description: string}  $b
     * @return array{label: string, source: string, category_a: string, category_b: string, a: array{title: string, description: string}, b: array{title: string, description: string}}
     */
    private function pair(string $label, string $source, string $categoryA, string $categoryB, array $a, array $b): array
    {
        return [
            'label' => $label,
            'source' => $source,
            'category_a' => $categoryA,
            'category_b' => $categoryB,
            'a' => ['title' => $a['title'], 'description' => $a['description']],
            'b' => ['title' => $b['title'], 'description' => $b['description']],
        ];
    }
}
